import java.util.*;record Book(String isbn,String title){}class Library{private final Map<String,Book> books=new LinkedHashMap<>();void add(Book book){books.put(book.isbn(),book);}Optional<Book> find(String isbn){return Optional.ofNullable(books.get(isbn));}}class Main{public static void main(String[] args){Library library=new Library();library.add(new Book("101","Java Basics"));System.out.println(library.find("101").map(Book::title).orElse("Not found"));}}
